'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var hasProp = require( '@stdlib/assert/has-property' );
var isNumber = require( '@stdlib/assert/is-number' );
var Padding = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Padding, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor returns an instance which has a `left` property', function test( t ) {
	var v;

	v = new Padding();
	t.strictEqual( hasOwnProp( v, 'left' ), false, 'returns expected value' );
	t.strictEqual( hasProp( v, 'left' ), true, 'returns expected value' );
	t.strictEqual( isNumber( v.left ), true, 'returns expected value' );

	t.end();
});

tape( 'the constructor throws an error if provided an invalid `left` option', function test( t ) {
	var values;
	var i;

	values = [
		'beep',
		'boop',
		null,
		true,
		false,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var padding = new Padding({ // eslint-disable-line no-unused-vars
				'left': value
			});
		};
	}
});

tape( 'the constructor returns an instance having a `left` property which throws an error if set to an invalid value', function test( t ) {
	var values;
	var i;

	values = [
		'beep',
		'boop',
		null,
		true,
		false,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var padding = new Padding();
			padding.left = value;
		};
	}
});

tape( 'the constructor returns an instance having a `left` property', function test( t ) {
	var padding;

	padding = new Padding();
	t.strictEqual( padding.left, 0, 'returns expected value' );

	padding = new Padding({
		'left': 10
	});
	t.strictEqual( padding.left, 10, 'returns expected value' );

	padding = new Padding({
		'left': 20
	});
	t.strictEqual( padding.left, 20, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `left` property which can be set to a valid value', function test( t ) {
	var padding;

	padding = new Padding();

	padding.left = 10;
	t.strictEqual( padding.left, 10, 'returns expected value' );

	padding.left = 20;
	t.strictEqual( padding.left, 20, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance which emits an event when the `left` property is set to a new value', function test( t ) {
	var padding;
	var count;

	padding = new Padding();
	count = 0;

	padding.on( 'change', onChange );

	padding.left = 10;
	t.strictEqual( count, 1, 'returns expected value' );

	padding.left = 20;
	t.strictEqual( count, 2, 'returns expected value' );

	// Setting to the same value should not emit an event:
	padding.left = 20;
	t.strictEqual( count, 2, 'returns expected value' );

	t.end();

	function onChange() {
		count += 1;
	}
});
